-- BusinessOps AI PostgreSQL / Supabase starter schema.
-- Run in a fresh Supabase project. Auth users are mapped through profiles.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', created_at timestamptz not null default now());
create table if not exists public.businesses(id uuid primary key default gen_random_uuid(), name text not null, category text not null default 'Retail', currency char(3) not null default 'NPR', address text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.business_members(id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null check(role in ('owner','manager','staff')), created_at timestamptz not null default now(), unique(business_id,user_id));
create table if not exists public.customers(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),name text not null,phone text,email text,address text,created_at timestamptz not null default now());
create table if not exists public.suppliers(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),name text not null,contact text,phone text,email text,address text,payment_terms text,created_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),sku text,name text not null,category text not null default 'General',unit text not null default 'pcs',purchase_price numeric(14,2) not null default 0 check(purchase_price>=0),selling_price numeric(14,2) not null default 0 check(selling_price>=0),stock numeric(14,3) not null default 0 check(stock>=0),min_stock numeric(14,3) not null default 0 check(min_stock>=0),archived boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.sales(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),invoice_no text not null,total numeric(14,2) not null check(total>=0),paid numeric(14,2) not null default 0 check(paid>=0),cogs numeric(14,2) not null default 0,status text not null default 'approved',payment_method text not null default 'Cash',customer_id uuid references public.customers(id),created_at timestamptz not null default now(),unique(business_id,invoice_no));
create table if not exists public.sale_items(id uuid primary key default gen_random_uuid(),sale_id uuid not null references public.sales(id),product_id uuid not null references public.products(id),quantity numeric(14,3) not null check(quantity>0),unit_price numeric(14,2) not null check(unit_price>=0),unit_cost numeric(14,2) not null check(unit_cost>=0),line_total numeric(14,2) not null);
create table if not exists public.purchases(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),po_no text not null,total numeric(14,2) not null,paid numeric(14,2) not null default 0,status text not null default 'Order placed',expected_date date,supplier_id uuid references public.suppliers(id),created_at timestamptz not null default now(),unique(business_id,po_no));
create table if not exists public.purchase_items(id uuid primary key default gen_random_uuid(),purchase_id uuid not null references public.purchases(id),product_id uuid not null references public.products(id),ordered_qty numeric(14,3) not null,received_qty numeric(14,3) not null default 0,unit_cost numeric(14,2) not null,line_total numeric(14,2) not null);
create table if not exists public.expenses(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),category text not null,description text,amount numeric(14,2) not null check(amount>=0),date date not null default current_date);
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),type text not null,amount numeric(14,2) not null check(amount>0),method text not null default 'Cash',related_type text,related_id uuid,note text,created_at timestamptz not null default now());
create table if not exists public.inventory_transactions(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),product_id uuid not null references public.products(id),type text not null,quantity numeric(14,3) not null,reference text,created_at timestamptz not null default now());
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),title text not null,body text not null,category text not null default 'info',read boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),user_id uuid references auth.users(id),action text not null,entity text not null,entity_id uuid,details jsonb,created_at timestamptz not null default now());
create index if not exists products_business_idx on public.products(business_id);create index if not exists sales_business_created_idx on public.sales(business_id,created_at desc);create index if not exists purchases_business_idx on public.purchases(business_id);
create or replace function public.is_business_member(target_business uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.business_members m where m.business_id=target_business and m.user_id=auth.uid()) $$;
do $$ declare t text; begin foreach t in array array['businesses','business_members','customers','suppliers','products','sales','purchases','expenses','payments','inventory_transactions','notifications','audit_logs'] loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists business_member_access on public.%I',t); if t='business_members' then execute format('create policy business_member_access on public.%I for all using (user_id=auth.uid() or public.is_business_member(business_id)) with check (user_id=auth.uid() or public.is_business_member(business_id))',t); elsif t='businesses' then execute format('create policy business_member_access on public.%I for all using (public.is_business_member(id)) with check (public.is_business_member(id))',t); else execute format('create policy business_member_access on public.%I for all using (public.is_business_member(business_id)) with check (public.is_business_member(business_id))',t); end if; end loop; end $$;
-- Supporting operational tables from the full specification.
create table if not exists public.product_categories(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),name text not null,unique(business_id,name));
create table if not exists public.invoices(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),invoice_no text not null,customer_id uuid references public.customers(id),total numeric(14,2) not null,status text not null default 'draft',created_at timestamptz not null default now());
create table if not exists public.invoice_items(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.invoices(id),product_id uuid references public.products(id),description text,quantity numeric(14,3) not null,unit_price numeric(14,2) not null,line_total numeric(14,2) not null);
create table if not exists public.invoice_documents(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),invoice_id uuid references public.invoices(id),storage_path text not null,mime_type text not null,ocr_status text not null default 'pending_review',extracted_data jsonb,created_at timestamptz not null default now());
create table if not exists public.goods_receipts(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),purchase_id uuid not null references public.purchases(id),receipt_no text not null,received_at timestamptz not null default now(),notes text);
create table if not exists public.goods_receipt_items(id uuid primary key default gen_random_uuid(),receipt_id uuid not null references public.goods_receipts(id),purchase_item_id uuid not null references public.purchase_items(id),quantity numeric(14,3) not null check(quantity>0));
create table if not exists public.stock_alerts(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),product_id uuid not null references public.products(id),alert_type text not null,status text not null default 'open',message text not null,created_at timestamptz not null default now());
create table if not exists public.expense_categories(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),name text not null,unique(business_id,name));
create table if not exists public.accounts_receivable(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),sale_id uuid not null references public.sales(id),amount_due numeric(14,2) not null,amount_paid numeric(14,2) not null default 0,due_date date,status text not null default 'unpaid');
create table if not exists public.accounts_payable(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),purchase_id uuid not null references public.purchases(id),amount_due numeric(14,2) not null,amount_paid numeric(14,2) not null default 0,due_date date,status text not null default 'unpaid');
create table if not exists public.demand_forecasts(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id),product_id uuid not null references public.products(id),forecast_start date not null,forecast_end date not null,predicted_quantity numeric(14,3) not null,reliability text not null,method text not null,created_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['product_categories','invoices','invoice_items','invoice_documents','goods_receipts','goods_receipt_items','stock_alerts','expense_categories','accounts_receivable','accounts_payable','demand_forecasts'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
-- Membership policies for tables that carry business_id directly.
do $$ declare t text; begin foreach t in array array['product_categories','invoices','invoice_documents','goods_receipts','stock_alerts','expense_categories','accounts_receivable','accounts_payable','demand_forecasts'] loop execute format('drop policy if exists business_member_access on public.%I',t); execute format('create policy business_member_access on public.%I for all using (public.is_business_member(business_id)) with check (public.is_business_member(business_id))',t); end loop; end $$;
-- Child rows are scoped through their parent records.
create policy invoice_items_business_access on public.invoice_items for all using (exists(select 1 from public.invoices i where i.id=invoice_id and public.is_business_member(i.business_id))) with check (exists(select 1 from public.invoices i where i.id=invoice_id and public.is_business_member(i.business_id)));
create policy goods_receipt_items_business_access on public.goods_receipt_items for all using (exists(select 1 from public.goods_receipts r where r.id=receipt_id and public.is_business_member(r.business_id))) with check (exists(select 1 from public.goods_receipts r where r.id=receipt_id and public.is_business_member(r.business_id)));
